    void ValidateUserStoredRun(Run r){var m=GetUserModel(r.Assembly);if(!r.Generic||m.Revision!=r.EditVersion||r.FileHashes==null||r.FileHashes.Any(p=>!File.Exists(p.Key)||FileHash(p.Key)!=p.Value))throw new Exception("MODEL_REVISION_CHANGED");var result=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(r.Directory,"solve.json")));if((string)result["result_validity"]!="verified")throw new Exception("RESULTS_UNVERIFIED");if(FileHash(Path.Combine(r.Directory,"component-poses.csv"))!=(string)result["poses_sha256"])throw new Exception("RESULT_ARTIFACT_CHANGED");}
    public object UserRunSummary(string id){var r=GetRun(id);ValidateUserStoredRun(r);return Json.DeserializeObject(File.ReadAllText(Path.Combine(r.Directory,"solve.json")));}
    public object ExportUserCurve(string id,string componentId,string quantity,string axis){var r=GetRun(id);if(!r.Generic||!r.ComponentNames.ContainsKey(componentId))throw new Exception("RUN_COMPONENT_NOT_FOUND");if(!new[]{"position","displacement","linear_velocity","angular_velocity"}.Contains(quantity)||!new[]{"x","y","z","magnitude"}.Contains(axis))throw new Exception("CURVE_OPTIONS_UNSUPPORTED");ValidateUserStoredRun(r);{var p=r.Poses[r.ComponentNames[componentId]];var vectors=new double[p.Length][];string unit=quantity=="linear_velocity"?"m/s":quantity=="angular_velocity"?"rad/s":"m";
            for(int i=0;i<p.Length;i++){if(quantity=="position")vectors[i]=p[i].Skip(9).Take(3).ToArray();else if(quantity=="displacement")vectors[i]=p[i].Skip(9).Take(3).Zip(p[0].Skip(9).Take(3),(a,b)=>a-b).ToArray();else{int a=i==0?0:i-1,b=i==p.Length-1?i:i+1;double dt=r.Times[b]-r.Times[a];vectors[i]=quantity=="angular_velocity"?RotationIncrement(p[a],p[b]).Select(x=>x/dt).ToArray():p[b].Skip(9).Take(3).Zip(p[a].Skip(9).Take(3),(x,y)=>(x-y)/dt).ToArray();}}
            int k=axis=="x"?0:axis=="y"?1:2;var values=vectors.Select(v=>axis=="magnitude"?Math.Sqrt(v.Sum(x=>x*x)):v[k]).ToArray();string path=Path.Combine(r.Directory,componentId+"_"+quantity+"_"+axis+".csv");using(var csv=new StreamWriter(path)){csv.WriteLine("time_s,value_"+unit.Replace("/","_per_"));for(int i=0;i<values.Length;i++)csv.WriteLine(r.Times[i].ToString("R",CultureInfo.InvariantCulture)+","+values[i].ToString("R",CultureInfo.InvariantCulture));}return new{run_id=id,component_id=componentId,instance=r.ComponentNames[componentId],quantity=quantity,axis=axis,unit=unit,coordinate_frame="assembly_global",reference_point="component_coordinate_origin_not_center_of_mass",source=quantity.Contains("velocity")?"numeric_derivative_of_solver_poses":"solver_component_origin_pose",derivative_scheme="central_difference_interior_one_sided_endpoints",sample_count=values.Length,min=values.Min(),max=values.Max(),csv_path=path,warning="sampled pose derivatives; not a native instantaneous velocity plot; rotation aliasing possible for unvalidated existing drives"};}}
    public object ReplayUserFrame(string id,int frame){var r=GetRun(id);if(!r.Generic||frame<0||frame>=r.Times.Length)throw new Exception("FRAME_OUTSIDE_RUN");ValidateUserStoredRun(r);LoadUserMotion();var s=new Scope(this,r.Path,r.Study);string image=null;double delta=0;try{s.Study.Stop();if(s.Study.IsPlaying)throw new Exception("STUDY_PLAYING_STOP_REQUIRED");s.Study.SetTime(0);Application.DoEvents();RequireUserReady(GetUserModel(r.Assembly),s.Doc,r.Study);s.Study.SetDuration(r.Duration);((IMotionStudyProperties)s.Study.GetProperties(4)).SetFrameRate(r.Fps);if(!s.Doc.EditRebuild3())throw new Exception("REBUILD_FAILED");if(!s.Study.Calculate())throw new Exception("SOLVER_FAILED");var native=(IMotionStudyResults)s.Study.GetResults(4);if(native==null||native.IsOutOfDate())throw new Exception("RESULTS_STALE");var times=VerifiedUserTimes(s.Study,s.Doc,r.Duration,r.Fps,r.Directory,r.Times);if(!s.Study.SetTime(Argument(r.Times[frame],r.Duration)))throw new Exception("SOLVER_TIME_SELECTION_FAILED");Application.DoEvents();delta=Transforms(s.Doc).Max(p=>p.Value.Zip(r.Poses[p.Key][frame],(a,b)=>Math.Abs(a-b)).Max());var actual=Transforms(s.Doc);var expected=r.Poses.ToDictionary(p=>p.Key,p=>p.Value[frame]);var difference=PoseDifference(expected,actual);var components=actual.Select(p=>new{instance=p.Key,translation_m=Math.Sqrt(Enumerable.Range(9,3).Sum(k=>Math.Pow(p.Value[k]-expected[p.Key][k],2))),rotation_coefficient_delta=Enumerable.Range(0,9).Max(k=>Math.Abs(p.Value[k]-expected[p.Key][k]))}).OrderByDescending(v=>Math.Max(v.translation_m,v.rotation_coefficient_delta)).Take(5).ToArray();double translationError=actual.Max(p=>PoseValidation.TranslationDistance(expected[p.Key],p.Value)),rotationError=actual.Max(p=>PoseValidation.RotationDistance(expected[p.Key],p.Value));bool matched=actual.All(p=>PoseValidation.Matches(expected[p.Key],p.Value));var replayDiagnostic=new{run_id=id,frame=frame,time_s=r.Times[frame],maximum_transform_delta=delta,maximum_translation_difference_m=tran