    public object CreateUserCheckpoint(string id){LoadUserMotion();var m=GetUserModel(id);using(var s=new Scope(this,m.Path,null)){Fingerprint(s.Doc,s.DocumentPath);SaveOwnedDocuments(m);var states=StudyStates(s.Doc);string cp=Guid.NewGuid().ToString("N"),dir=Path.Combine(m.Directory,"checkpoints",cp);Directory.CreateDirectory(dir);var files=new Dictionary<string,string>();foreach(string path in m.Files){string copy=Path.Combine(dir,Path.GetFileName(path));File.Copy(path,copy,false);files[path]=FileHash(copy);}var descriptor=new{checkpoint_id=cp,model_id=id,files=files,configuration=s.Doc.ConfigurationManager.ActiveConfiguration.Name,poses=Transforms(s.Doc),studies=states,model=m};AtomicJson(Path.Combine(dir,"checkpoint.json"),descriptor);return new{model_id=id,checkpoint_id=cp,file_count=files.Count,checkpoint_path=Path.Combine(dir,"checkpoint.json"),studies=states};}}
    public object ResetUserStudyTime(string id,string studyName){var cp=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(CreateUserCheckpoint(id)));var m=GetUserModel(id);try{using(var s=new Scope(this,m.Path,null)){var study=(IMotionStudy)((IMotionStudyManager)s.Doc.Extension.GetMotionStudyManager()).GetMotionStudy(studyName);if(study==null)throw new Exception("STUDY_NOT_FOUND");study.Stop();if(!study.IsActive&&!study.Activate())throw new Exception("STUDY_TIME_RESET_FAILED");if(Math.Abs(study.GetTime())>1e-8&&!study.SetTime(0))throw new Exception("STUDY_TIME_RESET_FAILED");Application.DoEvents();if(Math.Abs(study.GetTime())>1e-8||!study.IsActive)throw new Exception("STUDY_TIME_RESET_FAILED");Save(s.Doc,m.Path);m.Revision++;SaveUserModel(m);return new{model_id=id,study=studyName,time_s=study.GetTime(),active=study.IsActive,previous_checkpoint_id=cp["checkpoint_id"],results_invalidated=true,restoration_status="restored"};}}catch{RestoreUserCheckpoint(id,(string)cp["checkpoint_id"]);throw;}}
    void CloseUserDocuments(string[] paths){var documents=(Sw.GetDocuments() as object[]??new object[0]).Cast<IModelDoc2>().Select(doc=>new{path=doc.GetPathName(),title=doc.GetTitle(),type=doc.GetType()}).Where(doc=>paths.Contains(doc.path,StringComparer.OrdinalIgnoreCase)).OrderByDescending(doc=>doc.type).ToArray();foreach(var item in documents)if((Sw.GetDocuments() as object[]??new object[0]).Cast<IModelDoc2>().Any(doc=>doc.GetPathName().Equals(item.path,StringComparison.OrdinalIgnoreCase)))Sw.CloseDoc(item.title);}
